import{_ as l,o as i,c as e,a2 as r}from"./chunks/framework.CdvW4CUT.js";const q=JSON.parse('{"title":"Discord文字頻道","description":"Discord文字頻道介紹。","frontmatter":{"title":"Discord文字頻道","description":"Discord文字頻道介紹。"},"headers":[],"relativePath":"discord/text_channel/index.md","filePath":"discord/text_channel.md"}'),h={name:"discord/text_channel/index.md"};function o(t,a,d,n,u,c){return i(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="discord文字頻道" tabindex="-1">Discord文字頻道 <a class="header-anchor" href="#discord文字頻道" aria-label="Permalink to &quot;Discord文字頻道&quot;">​</a></h1><p>傳送文字訊息的頻道，下面詳列各頻道功能與介紹</p><h2 id="規範與公告" tabindex="-1">規範與公告 <a class="header-anchor" href="#規範與公告" aria-label="Permalink to &quot;規範與公告&quot;">​</a></h2><h3 id="👜社群規範" tabindex="-1">👜社群規範 <a class="header-anchor" href="#👜社群規範" aria-label="Permalink to &quot;👜社群規範&quot;">​</a></h3><ul><li>伺服的<a href="/rule/chat/">公共頻道規範</a>，所有於公開頻道的發言請遵守本規定</li></ul><h3 id="📢伺服日誌" tabindex="-1">📢伺服日誌 <a class="header-anchor" href="#📢伺服日誌" aria-label="Permalink to &quot;📢伺服日誌&quot;">​</a></h3><ul><li>伺服的重大更新、活動、公告等資訊都會發布在這裡</li><li>請玩家密切關注此頻道的訊息，以確保了解伺服的更新資訊</li></ul><h3 id="🔨更新和維護" tabindex="-1">🔨更新和維護 <a class="header-anchor" href="#🔨更新和維護" aria-label="Permalink to &quot;🔨更新和維護&quot;">​</a></h3><ul><li>伺服的小更新、維護、停機等資訊都會發布在這裡</li><li>請玩家密切關注此頻道的訊息，以確保了解伺服的維護資訊</li></ul><h2 id="公開聊天室" tabindex="-1">公開聊天室 <a class="header-anchor" href="#公開聊天室" aria-label="Permalink to &quot;公開聊天室&quot;">​</a></h2><h3 id="🌅聊天室" tabindex="-1">🌅聊天室 <a class="header-anchor" href="#🌅聊天室" aria-label="Permalink to &quot;🌅聊天室&quot;">​</a></h3><ul><li>不限主題聊天，平時的聊天請多加善用這裡</li></ul><h3 id="🔎風平休憩區" tabindex="-1">🔎風平休憩區 <a class="header-anchor" href="#🔎風平休憩區" aria-label="Permalink to &quot;🔎風平休憩區&quot;">​</a></h3><ul><li>論壇式的聊天頻道，平時的聊天請多加善用這裡</li></ul><h2 id="同步頻道" tabindex="-1">同步頻道 <a class="header-anchor" href="#同步頻道" aria-label="Permalink to &quot;同步頻道&quot;">​</a></h2><h3 id="💻公共同步頻道" tabindex="-1">💻公共同步頻道 <a class="header-anchor" href="#💻公共同步頻道" aria-label="Permalink to &quot;💻公共同步頻道&quot;">​</a></h3><ul><li>此頻道的訊息會與伺服內聊天室雙向同步</li><li>需綁定遊戲帳號才可在此頻道發言<a href="/discord/">連結綁定</a></li><li>此頻道的所有發言，皆視為在遊戲內說話，請遵守<a href="/rule/">伺服規定</a></li></ul><h2 id="mc伺服事務處理" tabindex="-1">MC伺服事務處理 <a class="header-anchor" href="#mc伺服事務處理" aria-label="Permalink to &quot;MC伺服事務處理&quot;">​</a></h2><h3 id="🚔檢舉回報" tabindex="-1">🚔檢舉回報 <a class="header-anchor" href="#🚔檢舉回報" aria-label="Permalink to &quot;🚔檢舉回報&quot;">​</a></h3><ul><li>若要檢舉玩家，請使用此頻道</li><li>檢舉方式與格式請參考<a href="/apply/report/">檢舉破壞</a></li><li>若要調解請直接在該案件貼文中進行，或利用<a href="/discord/customer_service/">客服系統</a>進行</li><li>非案件相關人士請勿在此聊天</li></ul><h3 id="🧬開發辦公室" tabindex="-1">🧬開發辦公室 <a class="header-anchor" href="#🧬開發辦公室" aria-label="Permalink to &quot;🧬開發辦公室&quot;">​</a></h3><ul><li>若遊玩時有遇到任何問題，可在此發問(也可使用<a href="/discord/customer_service/">客服系統</a>)</li><li>有任何對伺服的想法或意見也可在此提出，鼓勵玩家多多參與</li><li>請不要出現&quot;伺服內部無關的事情/與伺服無關的問題/無意義且無法幫助的回答&quot;</li></ul><h3 id="🏪商店街與標案" tabindex="-1">🏪商店街與標案 <a class="header-anchor" href="#🏪商店街與標案" aria-label="Permalink to &quot;🏪商店街與標案&quot;">​</a></h3><ul><li>有關商店街及官方標案的資訊會於此宣布</li><li>有關商店的事務申請請參考<a href="/apply/form_shop/">事務申請</a></li></ul><h3 id="🎨伺服圖分享" tabindex="-1">🎨伺服圖分享 <a class="header-anchor" href="#🎨伺服圖分享" aria-label="Permalink to &quot;🎨伺服圖分享&quot;">​</a></h3><ul><li>歡迎大家在這邊貼出在本伺服遊玩的圖片 <ul><li>請勿張貼非本伺服的圖片</li></ul></li><li>請盡量不要在這邊聊天</li></ul><h3 id="🧩大廳與美術" tabindex="-1">🧩大廳與美術 <a class="header-anchor" href="#🧩大廳與美術" aria-label="Permalink to &quot;🧩大廳與美術&quot;">​</a></h3><ul><li>大廳與美術館開發用的討論頻道</li><li>非相關工作人員請不要在這裡聊天</li></ul><h2 id="mc紀錄" tabindex="-1">MC紀錄 <a class="header-anchor" href="#mc紀錄" aria-label="Permalink to &quot;MC紀錄&quot;">​</a></h2><h3 id="🏹處分紀錄" tabindex="-1">🏹處分紀錄 <a class="header-anchor" href="#🏹處分紀錄" aria-label="Permalink to &quot;🏹處分紀錄&quot;">​</a></h3><ul><li>存放玩家被暫時/永久停止提供遊玩服務的紀錄</li><li>存放玩家被暫時/永久限制公共頻道發言的紀錄</li></ul><h3 id="🎪商店事務" tabindex="-1">🎪商店事務 <a class="header-anchor" href="#🎪商店事務" aria-label="Permalink to &quot;🎪商店事務&quot;">​</a></h3><ul><li>商店街事務申請表單的紀錄</li><li>當我們處理完成後，會標記表情符號表示處理完成</li><li>有關商店街事務的申請請參考<a href="/apply/form_shop/">商店街事務</a></li></ul><h3 id="💵換錢處理" tabindex="-1">💵換錢處理 <a class="header-anchor" href="#💵換錢處理" aria-label="Permalink to &quot;💵換錢處理&quot;">​</a></h3><ul><li>商人換錢申請表單的紀錄</li><li>當我們處理完成後，會標記表情符號表示處理完成</li><li>有關商人換錢的申請請參考<a href="/apply/form_shop/">商店街事務</a></li></ul><h3 id="🌈畫作同步" tabindex="-1">🌈畫作同步 <a class="header-anchor" href="#🌈畫作同步" aria-label="Permalink to &quot;🌈畫作同步&quot;">​</a></h3><ul><li>畫作同步申請表單的紀錄</li><li>當我們處理完成後，會標記表情符號表示處理完成</li><li>有關畫作同步的申請請參考<a href="/apply/form_paint/">畫作同步</a></li></ul><h3 id="🎣上下線紀錄" tabindex="-1">🎣上下線紀錄 <a class="header-anchor" href="#🎣上下線紀錄" aria-label="Permalink to &quot;🎣上下線紀錄&quot;">​</a></h3><ul><li>存放玩家的上下線紀錄(位於『💻公共同步頻道』的討論串)</li></ul><h3 id="🌍dc自動訊息" tabindex="-1">🌍dc自動訊息 <a class="header-anchor" href="#🌍dc自動訊息" aria-label="Permalink to &quot;🌍dc自動訊息&quot;">​</a></h3><ul><li>存放玩家進入伺服Discord時的系統訊息</li></ul><h2 id="公眾與說明" tabindex="-1">公眾與說明 <a class="header-anchor" href="#公眾與說明" aria-label="Permalink to &quot;公眾與說明&quot;">​</a></h2><h3 id="🔰新人大廳" tabindex="-1">🔰新人大廳 <a class="header-anchor" href="#🔰新人大廳" aria-label="Permalink to &quot;🔰新人大廳&quot;">​</a></h3><ul><li>Discord的加入、退出訊息</li><li>本頻道僅能讀取訊息</li></ul><h3 id="🎯身份綁定" tabindex="-1">🎯身份綁定 <a class="header-anchor" href="#🎯身份綁定" aria-label="Permalink to &quot;🎯身份綁定&quot;">​</a></h3><ul><li>連結伺服角色與Discord帳號</li><li>詳細說明請參考<a href="/discord/">連結綁定說明</a></li></ul><h2 id="客服系統" tabindex="-1">客服系統 <a class="header-anchor" href="#客服系統" aria-label="Permalink to &quot;客服系統&quot;">​</a></h2><h3 id="📫客服系統" tabindex="-1">📫客服系統 <a class="header-anchor" href="#📫客服系統" aria-label="Permalink to &quot;📫客服系統&quot;">​</a></h3><ul><li>伺服器的客服系統，如果你有任何事情需要我們協助，請使用此管道與我們聯繫</li><li>詳細說明請參考<a href="/discord/customer_service/">客服系統</a></li></ul><h2 id="封存頻道" tabindex="-1">封存頻道 <a class="header-anchor" href="#封存頻道" aria-label="Permalink to &quot;封存頻道&quot;">​</a></h2><h3 id="⛳活動企劃" tabindex="-1">⛳活動企劃 <a class="header-anchor" href="#⛳活動企劃" aria-label="Permalink to &quot;⛳活動企劃&quot;">​</a></h3><ul><li><s>若伺服有舉辦任何活動需要報名或公告活動資訊，會在此頻道公告</s></li><li><s>活動期間可能會更改頻道名稱</s></li></ul><h3 id="🦖遊戲專區" tabindex="-1">🦖遊戲專區 <a class="header-anchor" href="#🦖遊戲專區" aria-label="Permalink to &quot;🦖遊戲專區&quot;">​</a></h3><ul><li><s>適合用來聊其他遊戲(不屬於本伺服)的地方</s></li></ul><p><a href="/discord/free_chat/">非公開頻道</a></p>',55)])])}const b=l(h,[["render",o]]);export{q as __pageData,b as default};
